-- lo18mv42gok004n
update public.exercises set consigne = '<p>Vous travaillez à plein temps et vous voulez suivre un cours pour vous détendre et apprendre quelque chose de nouveau. Vous choisissez le cours en fonction des critères suivants :</p><p>• cours le soir ou le week-end ;<br>• moins de 100 € au total ;<br>• petit groupe (10 personnes maximum) ;<br>• possibilité d''essayer avant de s''inscrire.</p><p>Vous comparez ces quatre annonces. Pour chaque annonce, cochez (☒) OUI si cela correspond au critère ou NON si cela ne correspond pas.</p>', reading_text = null where id = 'lo18mv42gok004n';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'tableau', 'Pour chaque annonce, cochez OUI ou NON.', '{"colonnes":[{"id":"lo18mv42gok004nc1","titre":"Atelier de photographie","texte":"<p>Vous rêvez de réussir enfin vos photos de voyage ? Notre atelier, animé par un photographe de presse, vous apprend à maîtriser la lumière, le cadrage et la retouche, avec votre propre appareil. Les séances ont lieu le mardi, de 19 h à 21 h, quand la plupart des participants ont fini leur journée de travail. Le cycle complet de dix séances revient à 120 €, sans compter les tirages papier. Comme nous tenons à ce que chacun puisse montrer ses images et poser ses questions, nous n''accueillons jamais plus de huit personnes. Attention : l''inscription vaut pour l''ensemble du cycle, et aucune séance de découverte n''est prévue.</p>"},{"id":"lo18mv42gok004nc2","titre":"Cours de cuisine du monde","texte":"<p>Chaque mois, un pays à l''honneur : le Maroc en septembre, le Japon en octobre, le Mexique en novembre. Le cours se déroule le samedi matin, de 9 h 30 à midi, dans la grande cuisine de la maison de quartier. Pour que l''ambiance reste conviviale, les participants cuisinent ensemble, à une douzaine autour du plan de travail, puis partagent le repas. Comptez 25 € la séance, ou 90 € si vous réservez d''un coup les quatre séances du trimestre. Vous hésitez ? Rien ne vous oblige à vous engager tout de suite : la première séance peut être réservée seule, et vous déciderez ensuite si vous continuez. Tablier et ingrédients fournis.</p>"},{"id":"lo18mv42gok004nc3","titre":"Espagnol pour débutants","texte":"<p>Vous partez bientôt en Espagne ou en Amérique latine ? Apprenez les bases de la langue avec Lucía, professeure native et diplômée. Les cours ont lieu en ligne, le lundi et le jeudi, de 12 h 15 à 13 h : l''idéal pour profiter de votre pause-déjeuner sans quitter le bureau. Les classes ne dépassent pas cinq élèves, ce qui laisse à chacun le temps de parler. Le trimestre complet coûte 85 €, supports de cours compris. Avant de vous décider, vous pouvez suivre un premier cours offert, sans aucune obligation de vous inscrire ensuite. Il suffit d''un ordinateur avec une caméra et un micro.</p>"},{"id":"lo18mv42gok004nc4","titre":"Théâtre d''improvisation","texte":"<p>Vous êtes timide, ou vous avez simplement envie de rire ? Le théâtre d''improvisation est fait pour vous. Rendez-vous chaque mercredi à 20 h, salle Molière, pour deux heures de jeux, d''exercices de voix et de petites scènes inventées sur le moment. Nos groupes réunissent entre quinze et vingt comédiens amateurs : plus on est nombreux, plus les scènes sont variées ! En fin d''année, un spectacle est présenté devant les familles. L''adhésion annuelle s''élève à 150 €, payables en trois fois. Pas sûr de vous ? Venez assister gratuitement à une séance en septembre, vous déciderez après.</p>"}],"criteres":[{"id":"lo18mv42gok004nt1","texte":"Horaires"},{"id":"lo18mv42gok004nt2","texte":"Prix"},{"id":"lo18mv42gok004nt3","texte":"Groupe"},{"id":"lo18mv42gok004nt4","texte":"Essai"}]}'::jsonb, '{"answers":{"lo18mv42gok004nt1_lo18mv42gok004nc1":"OUI","lo18mv42gok004nt2_lo18mv42gok004nc1":"NON","lo18mv42gok004nt3_lo18mv42gok004nc1":"OUI","lo18mv42gok004nt4_lo18mv42gok004nc1":"NON","lo18mv42gok004nt1_lo18mv42gok004nc2":"OUI","lo18mv42gok004nt2_lo18mv42gok004nc2":"OUI","lo18mv42gok004nt3_lo18mv42gok004nc2":"NON","lo18mv42gok004nt4_lo18mv42gok004nc2":"OUI","lo18mv42gok004nt1_lo18mv42gok004nc3":"NON","lo18mv42gok004nt2_lo18mv42gok004nc3":"OUI","lo18mv42gok004nt3_lo18mv42gok004nc3":"OUI","lo18mv42gok004nt4_lo18mv42gok004nc3":"OUI","lo18mv42gok004nt1_lo18mv42gok004nc4":"OUI","lo18mv42gok004nt2_lo18mv42gok004nc4":"NON","lo18mv42gok004nt3_lo18mv42gok004nc4":"NON","lo18mv42gok004nt4_lo18mv42gok004nc4":"OUI"}}'::jsonb, 'Atelier de photographie: « de 19 h à 21 h » (OUI), « revient à 120 € » (NON), « jamais plus de huit personnes » (OUI), « aucune séance de découverte n''est prévue » (NON). Cours de cuisine du monde: « le samedi matin » (OUI), « 90 € si vous réservez d''un coup les quatre séances » (OUI), « à une douzaine autour du plan de travail » (NON), « la première séance peut être réservée seule » (OUI). Espagnol pour débutants: « de 12 h 15 à 13 h » (NON), « Le trimestre complet coûte 85 € » (OUI), « ne dépassent pas cinq élèves » (OUI), « un premier cours offert » (OUI). Théâtre d''improvisation: « chaque mercredi à 20 h » (OUI), « L''adhésion annuelle s''élève à 150 € » (NON), « entre quinze et vingt comédiens amateurs » (NON), « assister gratuitement à une séance en septembre » (OUI).')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo18mv42gok004n' and q.ord = v.ord;
delete from public.questions where exercise_id = 'lo18mv42gok004n' and ord > 1;

-- lo18mv42gok004o
update public.exercises set consigne = '<p>Lisez l''article puis répondez aux questions.</p>' where id = 'lo18mv42gok004o';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Quelle situation l''article décrit-il au début ?', '{"options":["Des jeunes toujours connectés qui ne décrochent pas.","Des parents qui refusent de donner un téléphone à leurs enfants.","Des adolescents qui n''ont plus de forfait téléphonique."],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« Les adolescents ont un téléphone greffé à la main… mais ne répondent pas quand on les appelle ».'),
  (2, 'vf', 'Chez les adolescents, l''appel vocal reste le moyen de communication habituel.', '{"heSo":5}'::jsonb, '{"answer":1,"justification":"Chez les adolescents, l’appel vocal n’est plus le canal par défaut"}'::jsonb, null),
  (3, 'qcm', 'Dans quel cas un adolescent accepte-t-il encore d''appeler ?', '{"options":["quand il doit organiser une sortie avec plusieurs amis","quand il n''a plus de batterie","quand il a besoin d''être rassuré tout de suite"],"heSo":4}'::jsonb, '{"answer":2}'::jsonb, 'Cuộc gọi dành cho « situations urgentes, moments d’angoisse, besoin d’un réconfort immédiat ».'),
  (4, 'qcm', 'D''après l''auteure, pourquoi les adolescents préfèrent-ils écrire ?', '{"options":["L''écrit leur laisse le temps de choisir leurs mots.","Les appels coûtent plus cher que les messages écrits.","Ils sont trop paresseux pour parler."],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« Non pas par paresse », mà vì « On peut formuler, reformuler, supprimer, différer ».'),
  (5, 'vf', 'Répondre tout de suite au téléphone peut donner aux adolescents l''impression de perdre le contrôle.', '{"heSo":5}'::jsonb, '{"answer":0,"justification":"cette immédiateté est perçue comme un stress, une perte de contrôle"}'::jsonb, null),
  (6, 'qcm', 'Que montre le « petit rituel » cité dans l''article ?', '{"options":["Ils utilisent Snapchat seulement pour jouer.","Ils n''aiment plus parler à leurs amis.","Il est poli de demander avant d''appeler."],"heSo":4}'::jsonb, '{"answer":2}'::jsonb, '« sonder l’autre avant de se lancer dans un appel, devient une preuve de respect ».'),
  (7, 'qcm', 'Que propose l''auteure aux familles ?', '{"options":["interdire les messages pendant les repas","discuter des préférences de chacun","obliger les adolescents à répondre à tous les appels"],"heSo":4}'::jsonb, '{"answer":1}'::jsonb, '« une discussion franche et tranquille sur les préférences de chacun en matière de communication ».'),
  (8, 'qcm', 'Comment l''auteure voit-elle ce « silence téléphonique » ?', '{"options":["comme une occasion de changer nos habitudes","comme le signe d''une crise grave","comme un simple caprice d''adolescent"],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« pourquoi ne pas y lire une occasion de réinventer nos façons de se parler ? ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo18mv42gok004o' and q.ord = v.ord;
delete from public.questions where exercise_id = 'lo18mv42gok004o' and ord > 8;
